walkthrough_shape.text:
"""cabinet-rules: the T5.4 SHACL shape over the Cabinet's Turtle twin, served as one MCP tool (FastMCP, stdio).
Run:  python wire_shape_tool.py            (stdio MCP server)
      python wire_shape_tool.py --selftest (prints the verdict once)
"""
import json, pathlib, sys
import rdflib, pyshacl
from mcp.server.fastmcp import FastMCP

TWIN = rdflib.Graph().parse(pathlib.Path(__file__).resolve().parent.parent / "ttl" / "cabinet.ttl", format="turtle")
SHAPE = """@prefix sh:   <http://www.w3.org/ns/shacl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix x3do: <https://www.web3d.org/specifications/X3dOntology4.1#> .
@prefix lab:  <https://semantic-twin-lab.example/shapes#> .
@prefix xs:   <urn:x3d-mcp:shapes:x3d-core#> .

# Your own rule: no classic Material may be more than half transparent.
# xs:checkId and xs:fixHint are read by x3d_mcp shacl_validate into the verdict; other engines ignore them.
lab:HalfClear a sh:NodeShape ;
  sh:targetClass x3do:Material ;
  xs:checkId "half-clear" ;
  xs:fixHint "Lower transparency to 0.5 or less, or use a PhysicalMaterial for real glass." ;
  sh:property [ sh:path x3do:transparency ; sh:maxInclusive 0.5 ; sh:severity sh:Violation ;
                sh:message "Material is more than half transparent" ] ."""
SH = rdflib.Namespace("http://www.w3.org/ns/shacl#")
mcp = FastMCP("cabinet-rules")


@mcp.tool()
def check_half_clear() -> str:
    """Check the Cabinet against the lab rule 'no classic Material more than half transparent'.
    Returns JSON: conforms (SHACL: false on any result) and one row per result with focus, value, severity and message."""
    conforms, report, _ = pyshacl.validate(TWIN, shacl_graph=rdflib.Graph().parse(data=SHAPE, format="turtle"))
    rows = sorted(({"focus": str(report.value(r, SH.focusNode)).split("#")[-1], "value": str(report.value(r, SH.value)),
                    "severity": str(report.value(r, SH.resultSeverity)).split("#")[-1], "message": str(report.value(r, SH.resultMessage))}
                   for r in report.subjects(rdflib.RDF.type, SH.ValidationResult)), key=lambda x: x["focus"])
    return json.dumps({"conforms": bool(conforms), "results": rows})


if __name__ == "__main__":
    if "--selftest" in sys.argv:
        print(check_half_clear())
    else:
        mcp.run()
